<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_login();require_role('admin','staff');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));if($name===''){flash('danger','Tên nhà cung cấp là bắt buộc.');redirect('/suppliers.php');}$st=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$st->execute([$name,$phone?:null,$email?:null,$address?:null]);flash('success','Đã thêm nhà cung cấp.');redirect('/suppliers.php');}
$rows=$pdo->query('SELECT * FROM suppliers ORDER BY id DESC')->fetchAll();$pageTitle='Nhà cung cấp';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Nhà cung cấp</h1><p class="text-secondary mb-0">Thông tin liên hệ đối tác nhập hàng.</p></div></div><div class="row g-4"><div class="col-12 col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Thêm nhà cung cấp</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Tên</label><input name="name" class="form-control" required></div><div class="mb-3"><label class="form-label">Điện thoại</label><input name="phone" class="form-control"></div><div class="mb-3"><label class="form-label">Email</label><input type="email" name="email" class="form-control"></div><div class="mb-3"><label class="form-label">Địa chỉ</label><textarea name="address" class="form-control"></textarea></div><button class="btn btn-primary">Lưu</button></form></div></div></div><div class="col-12 col-lg-8"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Nhà cung cấp</th><th>Điện thoại</th><th>Email</th><th>Địa chỉ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td><?=e($r['address'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
